// App.js
import React, { useState } from 'react';
import { Routes, Route, useLocation } from 'react-router-dom';
import './App.css';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min.js';
import 'bootstrap-icons/font/bootstrap-icons.css';

// Pages
import Header from './Header';
import Footer from './Footer';
import Adminheader from './Pages/Adminpage/Adminheader';
import Home from './Pages/Home/Home';
import About from './Pages/About/About';
import Events from './Pages/Events/Events';
import Eventdetails from './Pages/Events/Eventdetails';
import Membership from './Pages/Membership/Membership';
import Contact from './Pages/Contact/Contact';
import Register from './Pages/Register/Register';
import Eventregistration from './Pages/Eventregistration/Eventregistration';
import Membershipregistration from './Pages/Membershipregistration/Membershipregistration';
import Login from './Pages/Login/Login';
import Carouselslider from './Carouselslider';

// Admin Pages
import Logindetails from './Pages/Adminpage/Logindetails';
import Registerdetails from './Pages/Adminpage/Registerdetails';
import Contactdetails from './Pages/Adminpage/Contactdetails';
import Membershipimg from './Pages/Adminpage/Membershipimg';
import Membershipdetails from './Pages/Adminpage/Membershipdetails';
import Admineventdetails from './Pages/Adminpage/Admineventdetails';

// Scroll to Top Component
import ScrollToTop from './ScrollToTop'; // ✅ Add this line

function App() {
  const location = useLocation();
  const normalizedPath = location.pathname.toLowerCase().replace(/\/+$/, '');
  const [sidebarWidth, setSidebarWidth] = useState('250px');

  // Admin and hidden route logic
  const adminPaths = [
    '/kai-kor/logindetails',
    '/kai-kor/registerdetails',
    '/kai-kor/contactdetails',
    '/kai-kor/membershipimg',
    '/kai-kor/membershipdetails',
    '/kai-kor/admineventdetails',
  ];

  const hiddenPaths = [
    '/kai-kor/login',
    '/kai-kor/register',
    ...adminPaths
  ];

  const isAdminPage = adminPaths.includes(normalizedPath);
  const showFooter = !hiddenPaths.includes(normalizedPath);

  return (
    <div className="App overflow-hidden">
      {/* Scroll to top on route change */}
      <ScrollToTop /> {/* ✅ Add this here */}

      {isAdminPage ? <Adminheader onToggleSidebar={setSidebarWidth} /> : <Header />}

      <div className={isAdminPage ? 'd-flex' : ''}>
        <div
          className={isAdminPage ? 'flex-grow-1' : ''}
          style={{
            marginLeft: isAdminPage ? sidebarWidth : '0',
            transition: 'margin-left 0.3s',
          }}
        >
          <div className="container-fluid px-0">
            <Routes>
              {/* Public Pages */}
              <Route path="/kai-kor/home" element={<Home />} />
              <Route path="/kai-kor/about" element={<About />} />
              <Route path="/kai-kor/events" element={<Events />} />
              <Route path="/kai-kor/eventdetails/:id" element={<Eventdetails />} />
              <Route path="/kai-kor/membership" element={<Membership />} />
              <Route path="/kai-kor/contact" element={<Contact />} />
              <Route path="/kai-kor/register" element={<Register />} />
              <Route path="/kai-kor/eventregistration" element={<Eventregistration />} />
              <Route path="/kai-kor/membershipregistration" element={<Membershipregistration />} />
              <Route path="/kai-kor/login" element={<Login />} />
              <Route path="/kai-kor/carouselslider" element={<Carouselslider />} />

              {/* Admin Pages */}
              <Route path="/kai-kor/logindetails" element={<Logindetails />} />
              <Route path="/kai-kor/registerdetails" element={<Registerdetails />} />
              <Route path="/kai-kor/contactdetails" element={<Contactdetails />} />
              <Route path="/kai-kor/membershipimg" element={<Membershipimg />} />
              <Route path="/kai-kor/membershipdetails" element={<Membershipdetails />} />
              <Route path="/kai-kor/admineventdetails" element={<Admineventdetails />} />
            </Routes>

            {showFooter && <Footer />}
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
